module lava_game (\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [3:0] N,\n    input wire [3:0] start_idx,\n    input wire [3:0] goal_idx,\n    input wire [7:0] A,\n    input wire [7:0] F,\n    input wire [31:0] rows_data,\n    input wire [31:0] cols_data,\n    output reg [1:0] result,\n    output reg done\n);\n\n    localparam [3:0] IDLE          = 4'd0;\n    localparam [3:0] BUILD_FATHER  = 4'd1;\n    localparam [3:0] FW_FATHER_K   = 4'd2;\n    localparam [3:0] FW_FATHER_I   = 4'd3;\n    localparam [3:0] FW_FATHER_J   = 4'd4;\n    localparam [3:0] SAVE_FATHER   = 4'd5;\n    localparam [3:0] BUILD_ELSA    = 4'd6;\n    localparam [3:0] FW_ELSA_K     = 4'd7;\n    localparam [3:0] FW_ELSA_I     = 4'd8;\n    localparam [3:0] FW_ELSA_J     = 4'd9;\n    localparam [3:0] COMPARE       = 4'd10;\n    localparam [3:0] DONE_STATE    = 4'd11;\n\n    localparam [1:0] SUCCESS     = 2'b00;\n    localparam [1:0] GO_FOR_IT   = 2'b01;\n    localparam [1:0] NO_CHANCE   = 2'b10;\n    localparam [1:0] NO_WAY      = 2'b11;\n\n    reg [3:0] state, next_state;\n    reg [3:0] i_cnt, j_cnt, k_cnt;\n    reg [3:0] rows [0:7];\n    reg [3:0] cols [0:7];\n    reg [3:0] dist_table [0:7][0:7];\n    reg [3:0] dist_father;\n    reg [3:0] dist_elsa;\n    reg [15:0] A_sq;\n    reg [3:0] N_reg;\n    reg [3:0] start_reg, goal_reg;\n    reg [7:0] F_reg;\n    integer i, j;\n\n    wire [3:0] row_i = rows[i_cnt];\n    wire [3:0] col_i = cols[i_cnt];\n    wire [3:0] row_j = rows[j_cnt];\n    wire [3:0] col_j = cols[j_cnt];\n\n    wire [3:0] row_diff = (row_i > row_j) ? (row_i - row_j) : (row_j - row_i);\n    wire [3:0] col_diff = (col_i > col_j) ? (col_i - col_j) : (col_j - col_i);\n    wire [15:0] euc_dist_sq = (row_diff * row_diff) + (col_diff * col_diff);\n\n    wire father_edge = ((row_i == row_j) && (col_diff <= F_reg[3:0])) || ((col_i == col_j) && (row_diff <= F_reg[3:0]));\n    wire elsas_edge = (euc_dist_sq <= A_sq);\n\n    wire [3:0] dist_ik = dist_table[i_cnt][k_cnt];\n    wire [3:0] dist_kj = dist_table[k_cnt][j_cnt];\n    wire [3:0] dist_ij = dist_table[i_cnt][j_cnt];\n    wire [3:0] new_dist = dist_ik + dist_kj;\n    wire update_condition = (dist_ik < 4'd15) && (dist_kj < 4'd15) && (new_dist < dist_ij);\n\n    always @(*) begin\n        next_state = state;\n        case (state)\n            IDLE: if (start) next_state = BUILD_FATHER;\n            BUILD_FATHER: begin\n                if (i_cnt == N_reg && j_cnt == N_reg) next_state = FW_FATHER_K;\n            end\n            FW_FATHER_K: begin\n                if (k_cnt == N_reg) next_state = SAVE_FATHER;\n                else next_state = FW_FATHER_I;\n            end\n            FW_FATHER_I: begin\n                if (i_cnt == N_reg) begin\n                    if (k_cnt == N_reg) next_state = SAVE_FATHER;\n                    else next_state = FW_FATHER_K;\n                end else next_state = FW_FATHER_J;\n            end\n            FW_FATHER_J: begin\n                if (j_cnt == N_reg) next_state = FW_FATHER_I;\n            end\n            SAVE_FATHER: next_state = BUILD_ELSA;\n            BUILD_ELSA: begin\n                if (i_cnt == N_reg && j_cnt == N_reg) next_state = FW_ELSA_K;\n            end\n            FW_ELSA_K: begin\n                if (k_cnt == N_reg) next_state = COMPARE;\n                else next_state = FW_ELSA_I;\n            end\n            FW_ELSA_I: begin\n                if (i_cnt == N_reg) begin\n                    if (k_cnt == N_reg) next_state = COMPARE;\n                    else next_state = FW_ELSA_K;\n                end else next_state = FW_ELSA_J;\n            end\n            FW_ELSA_J: begin\n                if (j_cnt == N_reg) next_state = FW_ELSA_I;\n            end\n            COMPARE: next_state = DONE_STATE;\n            DONE_STATE: next_state = IDLE;\n            default: next_state = IDLE;\n        endcase\n    end\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            done <= 1'b0;\n            result <= SUCCESS;\n            i_cnt <= 4'd0;\n            j_cnt <= 4'd0;\n            k_cnt <= 4'd0;\n            dist_father <= 4'd15;\n            dist_elsa <= 4'd15;\n            {rows[0], rows[1], rows[2], rows[3], rows[4], rows[5], rows[6], rows[7]} <= 32'd0;\n            {cols[0], cols[1], cols[2], cols[3], cols[4], cols[5], cols[6], cols[7]} <= 32'd0;\n            for (i = 0; i < 8; i = i + 1) begin\n                for (j = 0; j < 8; j = j + 1) begin\n                    dist_table[i][j] <= 4'd15;\n                end\n            end\n            A_sq <= 16'd0;\n            F_reg <= 8'd0;\n            N_reg <= 4'd0;\n            start_reg <= 4'd0;\n            goal_reg <= 4'd0;\n        end else begin\n            state <= next_state;\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    if (start) begin\n                        N_reg <= N;\n                        start_reg <= start_idx;\n                        goal_reg <= goal_idx;\n                        F_reg <= F;\n                        rows[0] <= rows_data[3:0];\n                        rows[1] <= rows_data[7:4];\n                        rows[2] <= rows_data[11:8];\n                        rows[3] <= rows_data[15:12];\n                        rows[4] <= rows_data[19:16];\n                        rows[5] <= rows_data[23:20];\n                        rows[6] <= rows_data[27:24];\n                        rows[7] <= rows_data[31:28];\n                        cols[0] <= cols_data[3:0];\n                        cols[1] <= cols_data[7:4];\n                        cols[2] <= cols_data[11:8];\n                        cols[3] <= cols_data[15:12];\n                        cols[4] <= cols_data[19:16];\n                        cols[5] <= cols_data[23:20];\n                        cols[6] <= cols_data[27:24];\n                        cols[7] <= cols_data[31:28];\n                        i_cnt <= 4'd0;\n                        j_cnt <= 4'd0;\n                        k_cnt <= 4'd0;\n                    end\n                end\n\n                BUILD_FATHER: begin\n                    if (i_cnt < N_reg) begin\n                        if (j_cnt < N_reg) begin\n                            if (i_cnt == j_cnt) dist_table[i_cnt][j_cnt] <= 4'd0;\n                            else dist_table[i_cnt][j_cnt] <= father_edge ? 4'd1 : 4'd15;\n                            j_cnt <= j_cnt + 4'd1;\n                        end else begin\n                            j_cnt <= 4'd0;\n                            i_cnt <= i_cnt + 4'd1;\n                        end\n                    end\n                end\n\n                FW_FATHER_K: begin\n                    i_cnt <= 4'd0;\n                    k_cnt <= k_cnt + 4'd1;\n                end\n\n                FW_FATHER_I: begin\n                    j_cnt <= 4'd0;\n                    i_cnt <= i_cnt + 4'd1;\n                end\n\n                FW_FATHER_J: begin\n                    if (j_cnt < N_reg) begin\n                        if (update_condition) dist_table[i_cnt][j_cnt] <= new_dist;\n                        j_cnt <= j_cnt + 4'd1;\n                    end\n                end\n\n                SAVE_FATHER: begin\n                    dist_father <= dist_table[start_reg][goal_reg];\n                    i_cnt <= 4'd0;\n                    j_cnt <= 4'd0;\n                end\n\n                BUILD_ELSA: begin\n                    A_sq <= A * A;\n                    if (i_cnt < N_reg) begin\n                        if (j_cnt < N_reg) begin\n                            if (i_cnt == j_cnt) dist_table[i_cnt][j_cnt] <= 4'd0;\n                            else dist_table[i_cnt][j_cnt] <= elsas_edge ? 4'd1 : 4'd15;\n                            j_cnt <= j_cnt + 4'd1;\n                        end else begin\n                            j_cnt <= 4'd0;\n                            i_cnt <= i_cnt + 4'd1;\n                        end\n                    end\n                end\n\n                FW_ELSA_K: begin\n                    i_cnt <= 4'd0;\n                    k_cnt <= k_cnt + 4'd1;\n                end\n\n                FW_ELSA_I: begin\n                    j_cnt <= 4'd0;\n                    i_cnt <= i_cnt + 4'd1;\n                end\n\n                FW_ELSA_J: begin\n                    if (j_cnt < N_reg) begin\n                        if (update_condition) dist_table[i_cnt][j_cnt] <= new_dist;\n                        j_cnt <= j_cnt + 4'd1;\n                    end\n                end\n\n                COMPARE: begin\n                    dist_elsa <= dist_table[start_reg][goal_reg];\n                    done <= 1'b1;\n                    if (dist_father == 4'd15 && dist_elsa == 4'd15) result <= NO_WAY;\n                    else if (dist_father == 4'd15) result <= GO_FOR_IT;\n                    else if (dist_elsa == 4'd15) result <= NO_CHANCE;\n                    else if (dist_elsa == dist_father) result <= SUCCESS;\n                    else if (dist_elsa < dist_father) result <= GO_FOR_IT;\n                    else result <= NO_CHANCE;\n                end\n\n                DONE_STATE: begin\n                    done <= 1'b1;\n                end\n            endcase\n        end\n    end\n\nendmodule